node -e '
import("./src/truncate.mjs").then(m=>{
  const t=m.truncate;
  console.log("ellipsis-len", JSON.stringify(t("abcdef",5)), t("abcdef",5).length);
  console.log("codepoint", t("abcdef",5).codePointAt(4).toString(16));
  for (const n of [1,2,3,5,8,20]) { const r=t("the quick brown fox jumps", n); console.log(n, r.length===n, JSON.stringify(r)); }
  console.log("exports", Object.keys(m));
})' && grep -n "truncate\|Unreleased\|padStart" CHANGELOG.md
